/* Integration Hub shared look. Import with  @import 'c/ihStyles';  */
:host {
    --ih-brand: #0b5cab;
    --ih-brand-dark: #032d60;
    --ih-brand-soft: #eef4ff;
    --ih-ink: #181818;
    --ih-ink-2: #444444;
    --ih-quiet: #5c5c5c;
    --ih-line: #e5e5e5;
    --ih-line-2: #f0f0f0;
    --ih-surface: #ffffff;
    --ih-canvas: #f3f3f3;
    --ih-ok: #2e844a;
    --ih-ok-bg: #e5f6e9;
    --ih-ok-ink: #194e31;
    --ih-bad: #ba0517;
    --ih-bad-bg: #fde8eb;
    --ih-bad-ink: #8e030f;
    --ih-warn: #dd7a01;
    --ih-warn-bg: #fff1e0;
    --ih-warn-ink: #7a3e00;
    --ih-info: #0176d3;
    --ih-info-bg: #e3effd;
    --ih-info-ink: #014486;
    --ih-purple-bg: #f1ebff;
    --ih-purple-ink: #5a1ba9;
    --ih-teal-bg: #def7f4;
    --ih-teal-ink: #05628a;
    --ih-radius: 12px;
    --ih-shadow: 0 1px 2px rgba(3, 45, 96, 0.06), 0 4px 14px rgba(3, 45, 96, 0.06);
    display: block;
    color: var(--ih-ink);
}

/* ---------- page structure ---------- */
.ih-page {
    display: flex;
    flex-direction: column;
    gap: 16px;
    padding-bottom: 1.5rem; /* keeps the last card off the page edge */
}
.ih-hero {
    position: relative;
    overflow: hidden;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 16px;
    padding: 20px 24px;
    border-radius: var(--ih-radius);
    color: #ffffff;
    background: linear-gradient(120deg, #032d60 0%, #0b5cab 62%, #1b96ff 100%);
    box-shadow: var(--ih-shadow);
}
.ih-hero::after {
    content: '';
    position: absolute;
    right: -60px;
    top: -80px;
    width: 260px;
    height: 260px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(255, 255, 255, 0.18), rgba(255, 255, 255, 0) 70%);
    pointer-events: none;
}
.ih-hero-icon {
    flex: 0 0 auto;
    width: 44px;
    height: 44px;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.16);
    display: inline-flex;
    align-items: center;
    justify-content: center;
}
.ih-hero-text {
    flex: 1 1 280px;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
}
.ih-eyebrow {
    font-size: 12px;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    opacity: 0.85;
}
.ih-hero h1 {
    margin: 0;
    font-size: 22px;
    line-height: 1.25;
    font-weight: 700;
}
.ih-hero p {
    margin: 0;
    opacity: 0.9;
    font-size: 13px;
}
.ih-hero-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    position: relative;
    z-index: 1;
}

.ih-card {
    background: var(--ih-surface);
    border: 1px solid var(--ih-line);
    border-radius: var(--ih-radius);
    box-shadow: var(--ih-shadow);
    min-width: 0;
}
.ih-card-head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 14px 20px;
    border-bottom: 1px solid var(--ih-line-2);
}
.ih-card-title {
    display: flex;
    align-items: center;
    gap: 10px;
    margin: 0;
    font-size: 15px;
    font-weight: 700;
}
.ih-card-body {
    padding: 16px 20px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}
.ih-card-foot {
    padding: 10px 20px 14px;
    border-top: 1px solid var(--ih-line-2);
    font-size: 12px;
    color: var(--ih-quiet);
}
.ih-grid-2 {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
    gap: 16px;
}
.ih-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
}
.ih-spacer {
    flex: 1 1 auto;
}

/* ---------- stat tiles ---------- */
.ih-tiles {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 12px;
}
.ih-tile {
    position: relative;
    background: var(--ih-surface);
    border: 1px solid var(--ih-line);
    border-radius: var(--ih-radius);
    box-shadow: var(--ih-shadow);
    padding: 14px 16px 14px 20px;
    display: flex;
    flex-direction: column;
    gap: 2px;
    text-align: left;
    cursor: pointer;
    font: inherit;
    color: inherit;
}
.ih-tile::before {
    content: '';
    position: absolute;
    left: 0;
    top: 12px;
    bottom: 12px;
    width: 4px;
    border-radius: 0 4px 4px 0;
    background: var(--ih-line);
}
.ih-tile:hover {
    border-color: #c9c9c9;
}
.ih-tile:focus-visible {
    outline: 2px solid var(--ih-brand);
    outline-offset: 2px;
}
.ih-tile.ih-tile_on {
    border-color: var(--ih-brand);
    background: var(--ih-brand-soft);
}
.ih-tile-label {
    font-size: 12px;
    color: var(--ih-quiet);
}
.ih-tile-value {
    font-size: 24px;
    font-weight: 700;
    line-height: 1.2;
    font-variant-numeric: tabular-nums;
}
.ih-tone_good::before { background: var(--ih-ok); }
.ih-tone_bad::before { background: var(--ih-bad); }
.ih-tone_warn::before { background: var(--ih-warn); }
.ih-tone_info::before { background: var(--ih-info); }
.ih-tone_brand::before { background: var(--ih-brand); }

/* ---------- tables ---------- */
.ih-table-wrap {
    overflow-x: auto;
}
.ih-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
}
.ih-table th {
    background: #fafaf9;
    text-align: left;
    color: var(--ih-quiet);
    font-weight: 600;
    font-size: 12px;
    padding: 10px 12px;
    border-bottom: 1px solid var(--ih-line);
    white-space: nowrap;
}
.ih-table td {
    padding: 11px 12px;
    border-bottom: 1px solid var(--ih-line-2);
    vertical-align: middle;
}
.ih-table tbody tr:hover td {
    background: #f8fbff;
}
.ih-table .first {
    padding-left: 20px;
}
.ih-table .last {
    padding-right: 20px;
}
.ih-nowrap {
    white-space: nowrap;
}
.ih-mono {
    font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
    font-size: 12px;
}
.ih-small {
    font-size: 12px;
    color: var(--ih-quiet);
}
/* "Auto-refreshing" hint shown while a component polls */
.ih-auto {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    white-space: nowrap;
}
.ih-hero .ih-auto {
    color: #ffffff;
    opacity: 0.85;
}
.ih-muted {
    color: var(--ih-quiet);
}
.ih-note {
    max-width: 300px;
    overflow-wrap: anywhere;
    color: var(--ih-ink-2);
}
.ih-note_bad {
    color: var(--ih-bad-ink);
}
.ih-link {
    color: var(--ih-brand);
    font-weight: 600;
    text-decoration: none;
    cursor: pointer;
}
.ih-link:hover {
    text-decoration: underline;
}

/* ---------- badges and tags ---------- */
.ih-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 2px 10px;
    border-radius: 999px;
    font-weight: 600;
    font-size: 12px;
    line-height: 20px;
    white-space: nowrap;
    background: #ececec;
    color: var(--ih-ink-2);
}
.ih-badge::before {
    content: '';
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: currentColor;
    opacity: 0.8;
}
.ih-badge_Success, .ih-badge_OK, .ih-badge_on { background: var(--ih-ok-bg); color: var(--ih-ok-ink); }
.ih-badge_Failed, .ih-badge_off_bad { background: var(--ih-bad-bg); color: var(--ih-bad-ink); }
.ih-badge_Abandoned { background: var(--ih-warn-bg); color: var(--ih-warn-ink); }
.ih-badge_Sent, .ih-badge_Retry, .ih-badge_Pending, .ih-badge_Received { background: var(--ih-info-bg); color: var(--ih-info-ink); }
.ih-badge_off { background: #ececec; color: var(--ih-quiet); }

.ih-tag {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 1px 8px;
    border-radius: 6px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.02em;
    white-space: nowrap;
}
.ih-tag_rest { background: var(--ih-info-bg); color: var(--ih-info-ink); }
.ih-tag_apex { background: var(--ih-purple-bg); color: var(--ih-purple-ink); }
.ih-tag_flow { background: var(--ih-teal-bg); color: var(--ih-teal-ink); }
.ih-tag_event { background: var(--ih-warn-bg); color: var(--ih-warn-ink); }
.ih-tag_mode { background: #f3f3f3; color: var(--ih-ink-2); }
.ih-tag_in { background: #e6f7ea; color: #0b5c2a; }
.ih-env {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 2px 10px;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 700;
    background: rgba(255, 255, 255, 0.92);
}
.ih-env_sandbox { color: #7a3e00; }
.ih-env_prod { color: #8e030f; }

/* ---------- messages ---------- */
.ih-callout {
    border-radius: 10px;
    padding: 12px 14px;
    font-size: 13px;
    display: flex;
    gap: 10px;
    align-items: flex-start;
}
.ih-callout_info { background: var(--ih-info-bg); color: var(--ih-info-ink); }
.ih-callout_bad { background: var(--ih-bad-bg); color: var(--ih-bad-ink); }
.ih-callout_ok { background: var(--ih-ok-bg); color: var(--ih-ok-ink); }
.ih-callout_warn { background: var(--ih-warn-bg); color: var(--ih-warn-ink); }
.ih-empty {
    padding: 28px 20px;
    text-align: center;
    color: var(--ih-quiet);
}
.ih-error {
    padding: 12px 20px;
    color: var(--ih-bad-ink);
}
.ih-spinner {
    position: relative;
    min-height: 3rem;
}
.ih-pre {
    margin: 0;
    padding: 12px 14px;
    background: #0f1b2d;
    color: #e6edf7;
    border-radius: 10px;
    font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
    font-size: 12px;
    line-height: 1.5;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    max-height: 420px;
    overflow: auto;
}
.ih-kv {
    display: grid;
    grid-template-columns: minmax(120px, 34%) 1fr;
    gap: 8px 16px;
    font-size: 13px;
}
.ih-kv dt {
    color: var(--ih-quiet);
}
.ih-kv dd {
    margin: 0;
    overflow-wrap: anywhere;
}
.ih-check {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    font-size: 13px;
}
.ih-ok-text { color: var(--ih-ok-ink); }
.ih-bad-text { color: var(--ih-bad-ink); }

/* ---------- inner tabs ---------- */
.ih-tabs {
    display: flex;
    gap: 4px;
    border-bottom: 1px solid var(--ih-line);
    overflow-x: auto;
}
.ih-tab {
    background: none;
    border: 0;
    border-bottom: 3px solid transparent;
    padding: 10px 14px 9px;
    font: inherit;
    font-size: 14px;
    color: var(--ih-quiet);
    cursor: pointer;
    white-space: nowrap;
}
.ih-tab:hover {
    color: var(--ih-ink);
}
.ih-tab_on {
    color: var(--ih-brand);
    font-weight: 700;
    border-bottom-color: var(--ih-brand);
}
.ih-tab:focus-visible {
    outline: 2px solid var(--ih-brand);
    outline-offset: -2px;
}
